package com.shopsphere.swing;import javax.swing.*;import java.awt.*;public class LoginFrame extends JFrame{JTextField e=new JTextField();JPasswordField p=new JPasswordField();public LoginFrame(){setTitle("ShopSphere Admin");setSize(400,280);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);JPanel x=new JPanel(new GridLayout(5,1,8,8));x.setBorder(BorderFactory.createEmptyBorder(25,30,25,30));x.add(new JLabel("Email"));x.add(e);x.add(new JLabel("Password"));x.add(p);JButton b=new JButton("Login");x.add(b);add(x);b.addActionListener(a->{if(e.getText().equals("admin@shopsphere.com")&&new String(p.getPassword()).equals("admin123")){new DashboardFrame().setVisible(true);dispose();}else JOptionPane.showMessageDialog(this,"Invalid credentials");});}public static void main(String[]a){SwingUtilities.invokeLater(()->new LoginFrame().setVisible(true));}}
